// GetItem 按稳定编号查询事项。返回独立副本：流经班次、历史事件与关闭时间
// 都与存储中的记录脱离，改动结果不影响系统保存的记录。
func (svc *Service) GetItem(id string) (Item, error) {
	it, _ := findItem(&svc.store.data, clean(id))
	if it == nil {
		return Item{}, fmt.Errorf("%w：事项 %s", ErrNotFound, id)
	}
	return cloneItem(*it), nil
}

// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
// 当前保存的处理结果是退回、却没有任何退回轮次记录时（旧数据缺失），仍在时间线
// 中呈现这次已发生的退回，处理人与处理时间各自使用该项当前保存的信息（缺失分别
// 标为未记录），并标明退回历史不完整、原因未记录；不编造轮次序号、原因、补充或
// 重新提交经过，也不拿交接发起时间补齐处理时间。待处理、确认接收、继续跟踪、
// 结果缺失或无法识别的记录不据残留的处理人与时间认定发生退回。
// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
// 交接编号排列。同一次接收若已出现在事项历史里只展示一次：除操作人与实际
// 时刻相同外，还须接收说明明确记载的交接编号、交班、接班班次与接收方式都与
// 交接清单一致；任一记载不一致，或说明缺少明确记载（旧数据、没有对应交接
// 清单的接收历史）时，事项历史原样保留，不凭空补交接编号。只读查询，
// 不改变事项、交接进度或班次结束时记录。
// 返回的整份结果是查询当时的独立副本，与班次报告同一约定：事项最新信息
// （含流经班次、历史事件与关闭时间）、处理经过（含各轮退回原因、补充说明与
// 补充时间）和各次交接当前结果（含处理时间与历次退回/补充记录）全部深拷贝，
// 处理经过与交接当前结果中同一次补充的时间也各是一份副本。调用方改动结果
// 不影响系统保存的数据与其他已取得的结果，系统随后的正常处理（补充后重新
// 提交、接收、修改、关闭等）也不会改写这份结果；再次查询才反映最新内容。
func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
	itemID = clean(itemID)
	d := &svc.store.data
	it, _ := findItem(d, itemID)
	if it == nil {
		return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
	}
	j := ItemJourney{Item: cloneItem(*it)}

	// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
	// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
	// 该轮重新提交、后续处理）。
	type keyedEvent struct {
		ev    JourneyEvent
		group string // "" 表示事项自身事件，否则为交接编号
		ord   int    // 同一（时刻、分组）内的先后
	}
	var events []keyedEvent
	seq := 0
	add := func(ev JourneyEvent, group string) {
		events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
		seq++
	}

	// 接收记录的合并判定集中在 receivedMerge（见 received_merge.go）：遍历各次
	// 交接清单时标记与某次接收同属一次的事项 received 事件，该事件随后只以信息
	// 更全的交接事件展示。未标记的 received 事件（缺交接编号或交班班次的旧
	// 说明、指向其他交接/班次/方式的说明、自由文字或残缺说明等）在下面原样保留。
	merge := newReceivedMerge(it.Events)

	hs := append([]Handover(nil), d.Handovers...)
	sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
	for k := range hs {
		h := &hs[k]
		e, _ := findEntry(h, itemID)
		if e == nil {
			continue
		}
		j.HasHandovers = true
		j.Results = append(j.Results, EntryView{
			HandoverID: h.ID,
			FromShift:  h.FromShiftID,
			ToShift:    h.ToShiftID,
			Entry:      cloneEntry(*e),
		})

		// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
		add(JourneyEvent{
			At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
			Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
		}, h.ID)
		for _, r := range e.Rounds {
			add(JourneyEvent{
				At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
				Kind: "return", Operator: r.ReturnOperator,
				HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
				RoundSeq: r.Seq, Reason: r.Reason,
			}, h.ID)
			if r.ResubmittedAt != nil {
				add(JourneyEvent{
					At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
					Kind: "resubmit", Operator: r.SupplementOperator,
					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
					RoundSeq: r.Seq, Supplement: r.Supplement,
					// 补充时间复制一份：处理经过与交接当前结果中同一次补充
					// 各属各的副本，改动其中一处不影响另一处与存储记录。
					SupplementOperator: r.SupplementOperator, SupplementAt: cloneTimePtr(r.SupplementAt),
				}, h.ID)
			}
		}
		if e.Status == EntryReturned && len(e.Rounds) == 0 {
			// 当前保存的结果是退回，却没有任何退回轮次记录（旧数据缺失）：
			// 退回确实发生过，处理经过必须呈现这一事实，不能像没发生过退回一样
			// 只列发起交接；但原因、轮次序号、补充与重新提交经过都没有可靠记录，
			// 只能使用该项当前保存的处理人与处理时间，并标明退回历史不完整。
			// 不编造第几次退回或退回原因，也不拿交接发起时间补齐处理时间。
			ev := JourneyEvent{
				Kind: "return-incomplete", Operator: e.Operator,
				HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
				HistoryIncomplete: true,
			}
			if validProcessedAt(e.ProcessedAt) {
				ev.At, ev.TimeKnown = *e.ProcessedAt, true
			}
			add(ev, h.ID)
		}
		if e.Status.Received() {
			rcpt := receiptFromEntry(h, e)
			ev := JourneyEvent{
				Kind: rcpt.kind, Operator: e.Operator,
				HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
				TrackingNote: e.TrackingNote,
				// 继续跟踪当时指定的后续负责人取自交接记录快照，
				// 之后修改事项负责人不改变这里的历史值。
				FollowOwner: e.FollowOwner,
			}
			// 处理时间缺失或为旧数据零值时仍保留该处理事件，
			// 时间标为未记录，排在有真实时间的事件之后；这种凭据 timeKnown
			// 为 false，consider 不会合并任何事项事件（也不拿发起时间代替）。
			if rcpt.timeKnown {
				ev.At, ev.TimeKnown = rcpt.at, true
			}
			add(ev, h.ID)
			// 标记与本次接收同属一次的事项 received 事件；合并依据全部在
			// sameReceivedEvent 中：操作人与实际时刻相同，且说明完整记载
			// 交接编号、交班、接班班次与接收方式并逐项一致。缺归属信息的
			// 旧说明、残缺或自由文字说明一律不合并，原样作为独立接收历史。
			merge.consider(rcpt)
		}
	}

	// 事项自身历史：建立、修改、关闭原样保留；未被合并掉的 received 事件
	// （旧数据、指向其他归属的说明、自由文字等）也原样保留。
	for i, iev := range it.Events {
		if iev.Kind == "received" && merge.isUsed(i) {
			continue
		}
		add(JourneyEvent{
			At: iev.At, TimeKnown: !iev.At.IsZero(),
			Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
		}, "")
	}

	sort.SliceStable(events, func(i, k int) bool {
		a, b := events[i], events[k]
		if a.ev.TimeKnown != b.ev.TimeKnown {
			return a.ev.TimeKnown
		}
		if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
			return a.ev.At.Before(b.ev.At)
		}
		if a.group != b.group {
			return a.group < b.group
		}
		return a.ord < b.ord
	})
	for _, ke := range events {
		j.Events = append(j.Events, ke.ev)
	}
	return j, nil
}

// GetHandover 按编号查询交接。返回独立副本：清单各项（含处理时间与历次
// 退回/补充记录）与完成时间都与存储中的记录脱离，改动结果不影响系统保存的记录。
func (svc *Service) GetHandover(id string) (Handover, error) {
	h, _ := findHandover(&svc.store.data, clean(id))
	if h == nil {
		return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
	}
	return cloneHandover(*h), nil
}

// ListHandovers 返回全部交接记录，按编号排序；每份交接都是独立副本。
func (svc *Service) ListHandovers() []Handover {
	out := make([]Handover, len(svc.store.data.Handovers))
	for i, h := range svc.store.data.Handovers {
		out[i] = cloneHandover(h)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// OverlapNotes 返回涉及指定班次的全部重叠说明。
func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
	shiftID = clean(shiftID)
	out := []OverlapNote{}
	for _, n := range svc.store.data.Notes {
		if n.ShiftA == shiftID || n.ShiftB == shiftID {
			out = append(out, n)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// cloneTimePtr 复制时间指针，nil 保持 nil。
func cloneTimePtr(t *time.Time) *time.Time {
	if t == nil {
		return nil
	}
	v := *t
	return &v
}

// cloneItem 深拷贝事项：流经班次、历史事件与关闭时间都与存储中的记录脱离。
func cloneItem(it Item) Item {
	out := it
	out.ShiftIDs = append([]string(nil), it.ShiftIDs...)
	out.Events = append([]ItemEvent(nil), it.Events...)
	out.ClosedAt = cloneTimePtr(it.ClosedAt)
	return out
}

// cloneCloseItemSnapshot 深拷贝结束时事项快照（含关闭时间指针）。
func cloneCloseItemSnapshot(s CloseItemSnapshot) CloseItemSnapshot {
	out := s
	out.ClosedAt = cloneTimePtr(s.ClosedAt)
	return out
}

// cloneCloseRecord 深拷贝班次结束时记录；nil 保持 nil，
// 空清单仍是非 nil 记录，与缺少结束时记录的旧数据相区别。
func cloneCloseRecord(rec *ShiftCloseRecord) *ShiftCloseRecord {
	if rec == nil {
		return nil
	}
	out := &ShiftCloseRecord{}
	if rec.Items != nil {
		out.Items = make([]CloseItemSnapshot, len(rec.Items))
		for i, s := range rec.Items {
			out.Items[i] = cloneCloseItemSnapshot(s)
		}
	}
	return out
}

// cloneShift 深拷贝班次：关闭时间与结束时记录都与存储中的记录脱离。
func cloneShift(sh Shift) Shift {
	out := sh
	out.ClosedAt = cloneTimePtr(sh.ClosedAt)
	out.CloseRecord = cloneCloseRecord(sh.CloseRecord)
	return out
}

// cloneEntry 深拷贝交接单项：处理时间与历次退回/补充记录都与存储中的记录脱离。
func cloneEntry(e HandoverEntry) HandoverEntry {
	out := e
	out.ProcessedAt = cloneTimePtr(e.ProcessedAt)
	if e.Rounds != nil {
		out.Rounds = make([]ReturnRound, len(e.Rounds))
		for i, r := range e.Rounds {
			out.Rounds[i] = r
			out.Rounds[i].SupplementAt = cloneTimePtr(r.SupplementAt)
			out.Rounds[i].ResubmittedAt = cloneTimePtr(r.ResubmittedAt)
		}
	}
	return out
}

// cloneHandover 深拷贝交接记录：完成时间与清单各项都与存储中的记录脱离。
func cloneHandover(h Handover) Handover {
	out := h
	out.CompletedAt = cloneTimePtr(h.CompletedAt)
	if h.Entries != nil {
		out.Entries = make([]HandoverEntry, len(h.Entries))
		for i, e := range h.Entries {
			out.Entries[i] = cloneEntry(e)
		}
	}
	return out
}

// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
// 返回的报告是查询当时的独立副本：班次信息、事项清单、结束时记录、最新状态
// 对照、关联交接与各项结果（含关闭时间、处理时间与历次退回补充记录）全部深拷贝，
// 调用方改动报告不影响系统保存的数据与其他已取得的报告，系统随后的正常处理
// 也不会改写这份报告；再次查询才反映最新内容。
func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
	shiftID = clean(shiftID)
	d := &svc.store.data
	rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
	sh, _ := findShift(d, shiftID)
	if sh == nil {
		return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
	}
	rep.Shift = cloneShift(*sh)

	for _, n := range d.Notes {
		if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
			rep.OverlapNotes = append(rep.OverlapNotes, n)
		}
	}
	sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })

	switch {
	case !sh.Closed:
		// 进行中的班次：事项可继续修改、关闭，展示当前信息。
		rep.Items = currentItemsOfShift(d, sh.ID)
	case sh.CloseRecord != nil:
		// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
		rep.ItemsAtClose = true
		rep.CloseItems = make([]CloseItemSnapshot, len(sh.CloseRecord.Items))
		for i, s := range sh.CloseRecord.Items {
			rep.CloseItems[i] = cloneCloseItemSnapshot(s)
		}
		sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
		for _, s := range rep.CloseItems {
			if it, _ := findItem(d, s.ItemID); it != nil {
				rep.LatestItems[s.ItemID] = cloneItem(*it)
			}
		}
	default:
		// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
		rep.HistoryIncomplete = true
		rep.Items = currentItemsOfShift(d, sh.ID)
	}
	sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
	for i := range rep.Items {
		rep.Items[i] = cloneItem(rep.Items[i])
	}

	for i := range d.Handovers {
		h := &d.Handovers[i]
		involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
		if !involved {
			continue
		}
		if h.FromShiftID == sh.ID {
			cp := cloneHandover(*h)
			rep.Outgoing = &cp
		}
		if h.ToShiftID == sh.ID {
			rep.Incoming = append(rep.Incoming, cloneHandover(*h))
		}
		for j := range h.Entries {
			rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
				HandoverID: h.ID,
				FromShift:  h.FromShiftID,
				ToShift:    h.ToShiftID,
				Entry:      cloneEntry(h.Entries[j]),
			})
		}
	}
	sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
	for k := range rep.Results {
		sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
	}
	return rep, nil
}

package handover

import (
	"errors"
	"strings"
	"time"
)

// Severity 是事项的严重程度。
type Severity string

const (
	SeverityNormal    Severity = "normal"    // 普通
	SeverityImportant Severity = "important" // 重要
	SeverityUrgent    Severity = "urgent"    // 紧急
)

// ParseSeverity 解析严重程度，接受英文标识与中文名称；空串非法。
func ParseSeverity(s string) (Severity, error) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "normal", "普通":
		return SeverityNormal, nil
	case "important", "重要":
		return SeverityImportant, nil
	case "urgent", "紧急":
		return SeverityUrgent, nil
	}
	return "", errors.New("严重程度无效：必须是 normal(普通)、important(重要)、urgent(紧急) 之一")
}

func (v Severity) valid() bool {
	return v == SeverityNormal || v == SeverityImportant || v == SeverityUrgent
}

// Label 返回严重程度的中文展示名。
func (v Severity) Label() string {
	switch v {
	case SeverityNormal:
		return "普通"
	case SeverityImportant:
		return "重要"
	case SeverityUrgent:
		return "紧急"
	}
	return string(v)
}

// EntryStatus 是交接事项的当前处理结果。
type EntryStatus string

const (
	EntryPending   EntryStatus = "pending"   // 待处理
	EntryConfirmed EntryStatus = "confirmed" // 确认接收
	EntryTracking  EntryStatus = "tracking"  // 继续跟踪（已接收）
	EntryReturned  EntryStatus = "returned"  // 退回
)

// Label 返回交接结果的中文展示名。缺失或空结果显示“处理结果未记录”；
// 不属于现有四种结果的原值显示“处理结果无法识别”并带出保存的原值，
// 不推测成任何一种已知结果。
func (s EntryStatus) Label() string {
	switch s {
	case EntryPending:
		return "待处理"
	case EntryConfirmed:
		return "确认接收"
	case EntryTracking:
		return "继续跟踪"
	case EntryReturned:
		return "退回"
	case "":
		return "处理结果未记录"
	}
	return "处理结果无法识别（原值：" + string(s) + "）"
}

// Received 报告该结果是否表示接班班次已经接收。
func (s EntryStatus) Received() bool {
	return s == EntryConfirmed || s == EntryTracking
}

// EntryAction 是接班人对单项交接事项可执行的操作。
type EntryAction string

const (
	ActionConfirm EntryAction = "confirm" // 确认接收
	ActionReturn  EntryAction = "return"  // 退回
	ActionTrack   EntryAction = "track"   // 继续跟踪
)

// ParseAction 解析交接操作，接受英文标识与中文名称。
func ParseAction(s string) (EntryAction, error) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "confirm", "确认", "确认接收":
		return ActionConfirm, nil
	case "return", "退回":
		return ActionReturn, nil
	case "track", "tracking", "继续跟踪", "跟踪":
		return ActionTrack, nil
	}
	return "", errors.New("操作无效：必须是 confirm(确认接收)、return(退回)、track(继续跟踪) 之一")
}

// Shift 是一个岗位班次，编号全局稳定。
type Shift struct {
	ID        string     `json:"id"`
	Position  string     `json:"position"`
	Owner     string     `json:"owner"`
	Start     time.Time  `json:"start"`
	End       time.Time  `json:"end"`
	CreatedAt time.Time  `json:"created_at"`
	Closed    bool       `json:"closed"`
	ClosedAt  *time.Time `json:"closed_at,omitempty"`
	// CloseRecord 是班次成功结束时留下的事项记录，一经写定不再随事项的后续
	// 修改、关闭或流转而改变。nil 表示该班次结束时未留下记录（旧数据）。
	CloseRecord *ShiftCloseRecord `json:"close_record,omitempty"`
}

// CloseItemSnapshot 冻结班次结束时刻某一事项的内容、严重程度、限制条件、
// 后续负责人与关闭情况。结束前已关闭的事项保留关闭人与关闭时间；
// 结束时未关闭的事项，之后无论由哪一班关闭，都不改变这里的未关闭记录。
type CloseItemSnapshot struct {
	ItemID        string     `json:"item_id"`
	Content       string     `json:"content"`
	Severity      Severity   `json:"severity"`
	Constraints   string     `json:"constraints,omitempty"`
	FollowOwner   string     `json:"follow_owner"`
	Closed        bool       `json:"closed"`
	ClosedAt      *time.Time `json:"closed_at,omitempty"`
	CloseOperator string     `json:"close_operator,omitempty"`
}

// ShiftCloseRecord 是班次成功结束时在班全部事项的冻结清单。
// Items 包含该班新增与已经接收的事项，也保留结束前已关闭的事项；
// 尚未确认或被退回的交接事项不在其中（仍留在交接记录里）。
// 空切片表示结束时没有事项，与缺少历史记录（CloseRecord 为 nil）相区别。
type ShiftCloseRecord struct {
	Items []CloseItemSnapshot `json:"items"`
}

// ItemEvent 是事项的追加式历史事件。
type ItemEvent struct {
	At       time.Time `json:"at"`
	Kind     string    `json:"kind"`
	Operator string    `json:"operator,omitempty"`
	Detail   string    `json:"detail,omitempty"`
}

// Item 是一项未关闭事项。编号全局稳定，跨班次交接保持不变。
type Item struct {
	ID             string      `json:"id"`
	OriginShiftID  string      `json:"origin_shift_id"`
	ShiftIDs       []string    `json:"shift_ids"`
	CurrentShiftID string      `json:"current_shift_id"`
	Content        string      `json:"content"`
	Severity       Severity    `json:"severity"`
	Constraints    string      `json:"constraints,omitempty"`
	FollowOwner    string      `json:"follow_owner"`
	CreatedAt      time.Time   `json:"created_at"`
	Closed         bool        `json:"closed"`
	ClosedAt       *time.Time  `json:"closed_at,omitempty"`
	CloseOperator  string      `json:"close_operator,omitempty"`
	Events         []ItemEvent `json:"events"`
}

// ReturnRound 记录一次退回以及交班人随后的补充说明与重新提交。
// 原文与退回原因一经写入不再覆盖。
type ReturnRound struct {
	Seq                int        `json:"seq"`
	ReturnedAt         time.Time  `json:"returned_at"`
	ReturnOperator     string     `json:"return_operator"`
	Reason             string     `json:"reason"`
	Supplement         string     `json:"supplement,omitempty"`
	SupplementOperator string     `json:"supplement_operator,omitempty"`
	SupplementAt       *time.Time `json:"supplement_at,omitempty"`
	ResubmittedAt      *time.Time `json:"resubmitted_at,omitempty"`
}

// HandoverEntry 是交接清单中的单项处理记录。
type HandoverEntry struct {
	ItemID       string        `json:"item_id"`
	Content      string        `json:"content"`
	Severity     Severity      `json:"severity"`
	Constraints  string        `json:"constraints,omitempty"`
	FollowOwner  string        `json:"follow_owner"`
	Status       EntryStatus   `json:"status"`
	Operator     string        `json:"operator,omitempty"`
	ProcessedAt  *time.Time    `json:"processed_at,omitempty"`
	TrackingNote string        `json:"tracking_note,omitempty"`
	Rounds       []ReturnRound `json:"rounds,omitempty"`
}

// Handover 是一个交班班次对接班班次发起的一次交接。
type Handover struct {
	ID          string    `json:"id"`
	Position    string    `json:"position"`
	FromShiftID string    `json:"from_shift_id"`
	ToShiftID   string    `json:"to_shift_id"`
	CreatedAt   time.Time `json:"created_at"`
	// CompletedAt 是整份交接真正接收齐全部事项的时刻。空清单在发起时即完成；
	// 非空清单在最后一项被确认接收或继续跟踪、整份交接首次全部明确接收时，
	// 以那次成功处理的时间为准。旧数据若在清单仍有结果缺失、无法识别、待处理
	// 或退回项时误写过完成时间（或只留下零值），接班人逐项补齐、最后一项成功
	// 接收时用本次处理时间覆盖旧时间，不沿用补齐前的时刻。单纯查询、补充后
	// 重新提交与重复发起都不更新它，也不为已全部接收但缺少完成时间的旧记录
	// 编造时刻。
	CompletedAt *time.Time      `json:"completed_at,omitempty"`
	Entries     []HandoverEntry `json:"entries"`
}

// Completed 报告交接是否已完成。完成以清单里每一项都明确为确认接收或
// 继续跟踪为准：待处理、退回、结果缺失（空）或无法识别都使交接保持未完成，
// 其他项全部已接收也不能抵消不确定项；空清单直接完成。判定只看清单中保存的
// 处理结果，不以已完成时间、事项所在班次、处理人或退回历史推测接收。
func (h *Handover) Completed() bool {
	for i := range h.Entries {
		if !h.Entries[i].Status.Received() {
			return false
		}
	}
	return true
}

// OverlapNote 记录同一岗位两个重叠班次的重叠说明。
type OverlapNote struct {
	ID        string    `json:"id"`
	Position  string    `json:"position"`
	ShiftA    string    `json:"shift_a"`
	ShiftB    string    `json:"shift_b"`
	Note      string    `json:"note"`
	CreatedAt time.Time `json:"created_at"`
}

// JourneyEvent 是事项处理经过中的一条记录：可能来自事项自身历史
// （建立/修改/关闭/接收），也可能来自它参与的交接（发起交接、逐轮退回、
// 补充后重新提交、确认接收、继续跟踪）。交接相关事件带有交接编号与交班、
// 接班班次；Operator 为空表示该操作人未记录（旧数据可能缺人名）。
type JourneyEvent struct {
	At                 time.Time  // 实际发生时刻；TimeKnown 为 false 表示未记录
	TimeKnown          bool       // At 是否有效（旧数据可能缺时间）
	Kind               string     // created/updated/closed/received/handover-init/return/return-incomplete/resubmit/confirm/track
	Operator           string     // 实际操作人；空表示未记录
	Detail             string     // 事项自身事件附带的说明
	// HistoryIncomplete 表示该事件由当前保存的处理结果推断而来（当前结果是退回
	// 却没有任何退回轮次记录）：退回确实发生过，但原因与轮次详情没有可靠记录，
	// 只展示当前保存的处理人与处理时间，并明确提示退回历史不完整。
	HistoryIncomplete bool
	HandoverID        string // 交接相关事件所属的交接编号
	FromShift          string     // 交班班次
	ToShift            string     // 接班班次
	RoundSeq           int        // 退回/重新提交的轮次
	Reason             string     // 该轮完整退回原因
	Supplement         string     // 该轮补充说明
	SupplementOperator string     // 补充人
	SupplementAt       *time.Time // 补充时间
	TrackingNote       string     // 继续跟踪的跟踪说明
	FollowOwner        string     // 继续跟踪当时指定的后续负责人（不随后续修改改变）
}

// ItemJourney 是凭事项编号查询得到的完整处理经过：开头为事项最新状态，
// Events 是合并事项自身历史与各次交接经过后的时间线，Results 是该事项在
// 每次交接中的当前处理结果。
type ItemJourney struct {
	Item         Item
	Events       []JourneyEvent // 按实际发生时刻排序（不同时区按同一实际时刻比较）
	Results      []EntryView    // 按交接编号排列
	HasHandovers bool           // false 表示尚未参与交接
}

// EntryView 把交接单项与其所属交接编号关联，用于按班次查询。
type EntryView struct {
	HandoverID string
	FromShift  string
	ToShift    string
	Entry      HandoverEntry
}

// ShiftReport 是按班次查询得到的完整视图。
type ShiftReport struct {
	Shift        Shift
	OverlapNotes []OverlapNote
	// Items 是进行中班次的当前事项，或旧数据班次（无结束时记录）的当前事项。
	Items []Item
	// CloseItems 是已结束班次结束时刻的事项快照（已冻结），按事项编号排列。
	CloseItems []CloseItemSnapshot
	// ItemsAtClose 为 true 表示本次查到了结束时记录，CloseItems 即结束时事实。
	ItemsAtClose bool
	// HistoryIncomplete 为 true 表示该已结束班次是旧数据、缺少结束时记录，
	// Items 只是当前信息，不能视为结束时事实。
	HistoryIncomplete bool
	// LatestItems 按事项编号索引结束时事项的最新状态，与结束时信息对照。
	LatestItems map[string]Item
	Outgoing    *Handover
	Incoming    []Handover
	// Results 按事项编号汇总它在历次交接中的当前结果与退回历史。
	Results map[string][]EntryView
}

package handover

import (
	"strings"
	"time"
)

// 本文件只承载 item-show 查询中的“接收记录合并”：判定事项自身历史里的
// received 事件与某次交接清单中的确认接收/继续跟踪是否同一次接收。
// 接班写盘（ProcessEntry）只用 receivedDetailText 生成说明；合并判定本身
// 是只读逻辑，不改变任何已保存数据，也不改变接班操作与数据格式。

// 事项历史中的接收说明模板。当前版本写入的 received 事件用交接编号、交班、
// 接班班次与接收方式完整标注；item-show 只有读到这种归属信息完整、且逐项
// 与交接清单一致的说明，才把它与清单接收认定为同一次接收。模板为固定格式，
// parseReceivedDetail 据其解析。
const (
	receivedDetailPrefix = "交接 "
	receivedDetailMid    = "（"
	receivedDetailArrow  = " -> "
	receivedDetailTail   = "）接班班次接收："
)

// 旧版本写入的接收说明形如“接班班次 S002 接收：继续跟踪…”：只明确记载接班
// 班次与接收方式，没有交接编号与交班班次。这种说明归属信息不完整，无法明确
// 认定是哪一次接收：它可能对应某次交接清单，也可能是清单之外的另一次接收
// （同一时刻、同一操作人、同一接班班次在业务上完全可能发生两次）。因此旧
// 格式一律不参与合并，只作为独立接收历史原样保留。

// receivedDetailText 生成接收事件的标准说明，明确记载交接编号、交班、接班班次
// 与接收方式；继续跟踪还保留当时的跟踪说明与后续负责人。
func receivedDetailText(h *Handover, action EntryAction, statusLabel, trackingNote, nextFollowOwner string) string {
	s := receivedDetailPrefix + h.ID + receivedDetailMid + h.FromShiftID +
		receivedDetailArrow + h.ToShiftID + receivedDetailTail + statusLabel
	if action == ActionTrack {
		s += "；跟踪说明：" + trackingNote + "；后续负责人：" + nextFollowOwner
	}
	return s
}

// receivedAttribution 是从接收说明中明确解析出的归属信息。只有四项全部有值
// 才可能用于合并判定；任何一项缺失都说明该说明归属不完整。
type receivedAttribution struct {
	handoverID string
	fromShift  string
	toShift    string
	kind       string // confirm/track，无法确定时为 ""
}

// receivedKindFromLabel 只识别两种已保存的接收方式中文名；track 的说明后还
// 带有“；跟踪说明：…”后缀。无法识别返回 ""，不据其他信息猜测。
func receivedKindFromLabel(label string) string {
	switch {
	case label == EntryConfirmed.Label():
		return "confirm"
	case label == EntryTracking.Label() || strings.HasPrefix(label, EntryTracking.Label()+"；"):
		return "track"
	}
	return ""
}

// complete 报告归属信息是否完整：交接编号、交班、接班班次与接收方式四项都
// 明确记载才算完整。缺任何一项（旧格式没有交接编号与交班班次）都无法明确
// 认定为某一次接收，不能据此合并。
func (a receivedAttribution) complete() bool {
	return a.handoverID != "" && a.fromShift != "" && a.toShift != "" && a.kind != ""
}

// parseReceivedDetail 解析本工具写入的固定格式说明（当前格式与旧版本格式），
// 提取其中明确记载的交接编号、交班、接班班次与接收方式。
//
// 只有当前版本的完整格式会返回 ok=true：四项归属信息都明确记载。旧版本格式
// 与残缺说明、自由文字一样返回 ok=false——旧格式不是解析失败，而是归属信息
// 不完整，仍按原文独立保留，绝不靠猜测补齐交接编号或交班班次。
func parseReceivedDetail(detail string) (receivedAttribution, bool) {
	if !strings.HasPrefix(detail, receivedDetailPrefix) {
		// 旧版本格式（“接班班次 S002 接收：…”）以及任何自由文字都没有
		// 明确记载完整归属，不参与合并。
		return receivedAttribution{}, false
	}
	rest := detail[len(receivedDetailPrefix):]
	pi := strings.Index(rest, receivedDetailMid)
	ai := strings.Index(rest, receivedDetailArrow)
	ti := strings.Index(rest, receivedDetailTail)
	if pi <= 0 || ai < 0 || ti < 0 || !(pi < ai && ai+len(receivedDetailArrow) < ti) {
		return receivedAttribution{}, false
	}
	attr := receivedAttribution{
		handoverID: rest[:pi],
		fromShift:  rest[pi+len(receivedDetailMid) : ai],
		toShift:    rest[ai+len(receivedDetailArrow) : ti],
		kind:       receivedKindFromLabel(rest[ti+len(receivedDetailTail):]),
	}
	if !attr.complete() {
		return receivedAttribution{}, false
	}
	return attr, true
}

// receivedReceipt 是一次交接清单接收处理（确认接收或继续跟踪）在合并判定中
// 使用的“接收凭据”：交接编号、交班与接班班次、接收方式，以及操作人与实际
// 发生时刻。处理时间缺失或为零值时不产生凭据（timeKnown=false）：这种记录
// 不参与合并，更不能拿交接发起时间代替。
type receivedReceipt struct {
	handoverID string
	fromShift  string
	toShift    string
	kind       string // confirm/track
	operator   string
	at         time.Time
	timeKnown  bool
}

// receiptFromEntry 从交接清单单项当前保存的接收结果构造凭据。只有结果明确为
// 确认接收或继续跟踪、且处理时间真实记录时才可用于合并；其余情况返回
// timeKnown=false。
func receiptFromEntry(h *Handover, e *HandoverEntry) receivedReceipt {
	rcpt := receivedReceipt{
		handoverID: h.ID,
		fromShift:  h.FromShiftID,
		toShift:    h.ToShiftID,
		operator:   e.Operator,
	}
	switch {
	case e.Status == EntryConfirmed:
		rcpt.kind = "confirm"
	case e.Status == EntryTracking:
		rcpt.kind = "track"
	default:
		return rcpt
	}
	if validProcessedAt(e.ProcessedAt) {
		rcpt.at, rcpt.timeKnown = *e.ProcessedAt, true
	}
	return rcpt
}

// sameReceivedEvent 判定一条事项自身 received 事件与一次交接接收是否明确为
// 同一次接收。所有条件都必须满足：
//   - 操作人相同、实际发生时刻相同（time.Time.Equal 按同一实际时刻比较，
//     不同时区写法表示同一时刻仍视为相同）；
//   - 接收说明必须是当前版本写入的完整固定格式，明确记载交接编号、交班、
//     接班班次与接收方式；旧版本格式（缺交接编号、交班班次）、自由文字或
//     残缺说明归属不完整，一律不合并且不补字段；
//   - 说明中明确记载的交接编号、交班、接班班次与接收方式逐项与清单凭据一致；
//     任一项指向其他交接、其他班次或另一种接收方式即为矛盾，保留原记录。
//
// 不能只因部分信息吻合（如同操作人、同时刻、同接班班次）就认定为同一次
// 接收，也不能因事项当前处于接班班次而合并。
func sameReceivedEvent(iev ItemEvent, rcpt receivedReceipt) bool {
	if iev.Kind != "received" || !iev.At.Equal(rcpt.at) || iev.Operator != rcpt.operator {
		return false
	}
	attr, ok := parseReceivedDetail(iev.Detail)
	if !ok {
		return false
	}
	return attr.handoverID == rcpt.handoverID &&
		attr.fromShift == rcpt.fromShift &&
		attr.toShift == rcpt.toShift &&
		attr.kind == rcpt.kind
}

// receivedMerge 在遍历各次交接清单时记录事项自身 received 事件中哪些与某次
// 交接接收同属一次。匹配后该事项事件在时间线中只以信息更全的交接事件展示；
// 未匹配的 received 事件由调用方原样保留。
//
// 一条事项事件至多匹配一次，一次交接接收至多匹配一条事项事件。逐条按事项
// 事件的保存顺序取第一条全部事实相符的记录，因此调换两条历史的保存顺序
// 不会改变结果：归属不完整（旧说明）或指向其他交接/班次/方式的记录会被
// 跳过，继续寻找真正同一次的完整记录，而不是隐藏它；只有部分信息吻合的
// 旧说明永远不会被标记，始终独立保留。
type receivedMerge struct {
	matched []bool
	events  []ItemEvent
}

func newReceivedMerge(events []ItemEvent) *receivedMerge {
	return &receivedMerge{matched: make([]bool, len(events)), events: events}
}

// consider 为一次交接接收标记同一次接收的事项事件；处理时间未记录的接收不
// 参与合并。调用顺序（各交接按编号排列）不影响最终匹配集合。
func (m *receivedMerge) consider(rcpt receivedReceipt) {
	if !rcpt.timeKnown {
		return
	}
	for i := range m.events {
		if m.matched[i] {
			continue
		}
		if sameReceivedEvent(m.events[i], rcpt) {
			m.matched[i] = true
			return
		}
	}
}

// isUsed 报告该事项事件是否已被某次交接接收合并。
func (m *receivedMerge) isUsed(i int) bool { return m.matched[i] }

